#ifndef VP_CONTACT_H
#define VP_CONTACT_H

#include "vp_math3.h"
#include "vp_config.h"

/* Contact flags (optional) */
enum {
    VP_CONTACT_FLAG_NONE       = 0,
    VP_CONTACT_FLAG_SENSOR     = 1 << 0, /* generates events but no impulses */
    VP_CONTACT_FLAG_SPECULATIVE= 1 << 1  /* penetration may be negative (separation) */
};

typedef struct vpContact {
    vp_u32 key;    /* stable key for lambda cache (generated by manifold system unless user provides) */
    vp_u16 bodyA;
    vp_u16 bodyB;
    vp_u8  flags;
    vp_u8  _pad;

    vpVec3 p;      /* contact point (world) */
    vpVec3 n;      /* normal (world), from A to B */
    vp_fx  penetration; /* >0 overlap, <0 separation (if speculative) */
    vp_fx  friction;
    vp_fx  restitution;
    vp_fx restitutionTarget; /* cached pre-solve separation velocity */

    vp_fx lambdaN;
    vp_fx lambdaT1;
    vp_fx lambdaT2;

#if VP_ENABLE_SPLIT_IMPULSE
    vp_fx lambdaBias; /* position-correction impulse accumulator (not cached) */
#endif
} vpContact;

/* lambda cache entry */
typedef struct vpContactCacheEntry {
    vp_u32 key;
    vp_u8  used;
    vp_fx  lambdaN;
    vp_fx  lambdaT1;
    vp_fx  lambdaT2;
} vpContactCacheEntry;

#endif /* VP_CONTACT_H */
